<template><div class="app-container ps-page"><h2>索引版本与回滚</h2><el-alert v-if="error||pageError" :title="error||pageError" type="error" :closable="false"/><div class="ps-toolbar"><el-button v-hasPermi="['paismart:index:rebuild']" type="primary" @click="open=true">重建索引</el-button><el-button :loading="loading" @click="load()">刷新版本</el-button><el-button v-hasPermi="['paismart:index:rebuild']" :loading="saving" @click="recover">恢复索引切换</el-button></div><el-table :data="rows" v-loading="loading"><el-table-column prop="name" label="索引版本" min-width="210"/><el-table-column prop="provider" label="供应商" min-width="140"/><el-table-column prop="model" label="模型快照" min-width="190"/><el-table-column prop="dimension" label="维度" width="80"/><el-table-column prop="documentCount" label="文档数" width="90"/><el-table-column prop="checkpoint" label="恢复断点" min-width="160"/><el-table-column label="状态" width="130"><template #default="{row}"><el-tag :type="row.active?'success':'info'">{{row.active?'当前索引':stateLabel(row.state)}}</el-tag></template></el-table-column><el-table-column prop="sourceWatermark" label="来源快照" min-width="180"/><el-table-column label="校验结果" width="120"><template #default="{row}"><el-button link @click="showValidation(row)">{{row.validation?.state||'未返回'}}</el-button></template></el-table-column><el-table-column label="操作" width="110"><template #default="{row}"><el-button v-hasPermi="['paismart:index:rollback']" link type="warning" :disabled="row.active||row.state!=='RETIRED'" @click="rollback(row)">回滚到此版</el-button></template></el-table-column></el-table><el-dialog v-model="open" title="重建或恢复索引" width="620px"><el-alert title="Embedding 模型和维度将冻结到新索引；构建完成并校验后才切换当前索引。" type="info" :closable="false" class="ps-section"/><el-form label-width="120px"><el-form-item label="目标供应商" required><el-select v-model="targetProvider"><el-option v-for="p in providers" :key="p.id" :label="`${p.provider} / ${p.model}`" :value="p.id"/></el-select></el-form-item><el-form-item label="构建方式"><el-radio-group v-model="fresh"><el-radio :value="true">新建版本</el-radio><el-radio :value="false">从检查点恢复</el-radio></el-radio-group></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!targetProvider" @click="rebuild">提交重建</el-button></template></el-dialog><el-drawer v-model="validationOpen" title="索引真实校验结果" size="min(700px,95vw)"><p>来源快照：{{selected?.sourceWatermark||'未返回'}}</p><el-alert v-if="!selected?.validation||selected.validation.state==='PENDING'" title="索引校验尚未完成，没有已验证的分块数量或查询结果。" type="info" :closable="false"/><pre class="ps-pre">{{JSON.stringify(selected?.validation??{},null,2)}}</pre></el-drawer><JobDialog v-model="jobOpen" :initial="job" @done="load()"/></div></template>
<script setup lang="ts">
import { onMounted,ref,shallowRef } from 'vue'
import { listIndexes,rebuildIndex,rollbackIndex,recoverIndex } from '@/api/paismart/governance'
import { listProviders } from '@/api/paismart/operations'
import { ElMessageBox } from 'element-plus'
import type { IndexRevision,Job,Provider } from '@/types/paismart'
import JobDialog from '../../components/JobDialog.vue'
import { errorText,stateLabel,usePage } from '../../composables/usePage'
import '../../common.css'
const selected=shallowRef<IndexRevision>(),validationOpen=ref(false)
function showValidation(row:IndexRevision){selected.value=row;validationOpen.value=true}
const {rows,loading,error,load}=usePage((_q,signal)=>listIndexes(signal)),providers=shallowRef<Provider[]>([]),job=shallowRef<Job>(),open=ref(false),jobOpen=ref(false),pageError=ref(''),formError=ref(''),saving=ref(false),targetProvider=ref(''),fresh=ref(true)
async function rebuild(){saving.value=true;formError.value='';try{job.value=(await rebuildIndex({targetProvider:targetProvider.value,fresh:fresh.value})).data;open.value=false;jobOpen.value=true;await load()}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
async function recover(){try{await ElMessageBox.confirm('读取持久化切换记录并恢复未完成的索引别名切换。','恢复索引切换',{type:'warning'});saving.value=true;job.value=(await recoverIndex()).data;jobOpen.value=true;await load()}catch(e){if(e!=='cancel'&&e!=='close')pageError.value=errorText(e)}finally{saving.value=false}}
async function rollback(row:IndexRevision){try{await ElMessageBox.confirm(`将当前检索切换回「${row.name}」，服务端将核对模型快照、对象和版本完整性。`, '回滚索引',{type:'warning'});job.value=(await rollbackIndex(row)).data;jobOpen.value=true;await load()}catch(e){if(e!=='cancel'&&e!=='close')pageError.value=errorText(e)}}
onMounted(async()=>{void load();try{providers.value=(await listProviders()).rows.filter(p=>p.scope.toUpperCase().includes('EMBED'));targetProvider.value=String(providers.value[0]?.id||'')}catch(e){pageError.value=errorText(e)}})
</script>
